Rule.Source:
     // Beanshell / IIQ rule script
import java.text.SimpleDateFormat;
import java.util.*;

import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import sailpoint.object.*;
import sailpoint.tools.GeneralException;
import sailpoint.tools.Util;

Logger logger = LogManager.getLogger("iiq.rule.WorkgroupEmptyOrInactiveMembershipNotification");

// ----- Config -----
String adminWorkgroupName = "AttributeSyncWorkGroup";
String emailTemplateName = "Workgroup Empty Or Inactive Membership Notification";
String activeStatusAttribute = "status";
String activeStatusValue = "Active";
String excludedWorkgroupsCsv = null;
String notificationTo = "gani@gmail.com"; // change as needed

if (Util.isNullOrEmpty(adminWorkgroupName)) {
    throw new GeneralException("Required argument 'adminWorkgroupName' is missing.");
}

// build excluded set
Set excludedWorkgroups = new LinkedHashSet();
if (Util.isNotNullOrEmpty(excludedWorkgroupsCsv)) {
    excludedWorkgroups.addAll(Arrays.asList(excludedWorkgroupsCsv.split(",")));
}

// Helper: build member query
QueryOptions buildMemberQuery(String workgroupName, String activeAttribute, String activeValue, boolean activeOnly) {
    QueryOptions qo = new QueryOptions();
    qo.add(Filter.eq("workgroup", false));
    qo.add(Filter.eq("workgroups.name", workgroupName));
    if (activeOnly) {
        qo.add(Filter.eq(activeAttribute, activeValue));
    }
    return qo;
}

// Helper: determine owner issue
String ownerIssue(Identity owner, String activeAttribute, String activeValue) {
    if (owner == null) {
        return "Owner does not exist in Identity";
    }
    if (owner.isWorkgroup()) {
        int activeMembersInOwnerWg = context.countObjects(Identity.class,
                buildMemberQuery(owner.getName(), activeAttribute, activeValue, true));
        if (activeMembersInOwnerWg == 0) {
            return "Owner workgroup has no active members";
        }
        return null;
    }
    String ownerStatus = owner.getStringAttribute(activeAttribute);
    if (Util.isNotNullOrEmpty(ownerStatus) && !activeValue.equalsIgnoreCase(ownerStatus)) {
        return "Owner inactive (" + ownerStatus + ")";
    }
    return null;
}

// Collections to hold findings (each entry is Map)
List workgroupFindings = new ArrayList();
List bundleFindings = new ArrayList();
List entitlementFindings = new ArrayList();

// 1) Workgroups
QueryOptions wgOptions = new QueryOptions();
wgOptions.add(Filter.eq("workgroup", true));
wgOptions.setOrderBy("name");
wgOptions.setOrderAscending(true);

Iterator wgIter = null;
try {
    wgIter = context.search(Identity.class, wgOptions);
    while (wgIter != null && wgIter.hasNext()) {
        Identity wg = (Identity) wgIter.next();
        String wgName = wg.getName();
        if (excludedWorkgroups.contains(wgName)) continue;

        int totalMembers = context.countObjects(Identity.class,
                buildMemberQuery(wgName, activeStatusAttribute, activeStatusValue, false));
        int activeMembers = context.countObjects(Identity.class,
                buildMemberQuery(wgName, activeStatusAttribute, activeStatusValue, true));

        String issueType = null;
        if (totalMembers == 0) issueType = "No members";
        else if (activeMembers == 0) issueType = "No active members";

        if (issueType != null) {
            Map f = new HashMap();
            f.put("workgroupName", wgName);
            f.put("displayName", Util.isNotNullOrEmpty(wg.getDisplayName()) ? wg.getDisplayName() : wgName);
            f.put("issueType", issueType);
            f.put("totalMembers", String.valueOf(totalMembers));
            f.put("activeMembers", String.valueOf(activeMembers));
            f.put("owner", (wg.getOwner() != null) ? wg.getOwner().getName() : "Unassigned");
            f.put("groupEmail", Util.isNotNullOrEmpty(wg.getEmail()) ? wg.getEmail() : "");
            workgroupFindings.add(f);
        }
    }
} finally {
    Util.flushIterator(wgIter);
}

// 2) Bundles
Iterator bundleIter = null;
try {
    QueryOptions bundleOptions = new QueryOptions();
    bundleOptions.setOrderBy("name");
    bundleOptions.setOrderAscending(true);
    bundleIter = context.search(Bundle.class, bundleOptions);
    while (bundleIter != null && bundleIter.hasNext()) {
        Bundle b = (Bundle) bundleIter.next();
        Identity owner = b.getOwner();
        String ownerIssueType = ownerIssue(owner, activeStatusAttribute, activeStatusValue);
        if (ownerIssueType != null) {
            Map f = new HashMap();
            f.put("bundleName", b.getName());
            f.put("displayName", Util.isNotNullOrEmpty(b.getDisplayName()) ? b.getDisplayName() : b.getName());
            f.put("ownerType", (owner == null) ? "N/A" : (owner.isWorkgroup() ? "Workgroup" : "Identity"));
            f.put("ownerName", (owner == null) ? "Not Found" : owner.getName());
            f.put("issueType", ownerIssueType);
            bundleFindings.add(f);
        }
    }
} finally {
    Util.flushIterator(bundleIter);
}

// 3) Entitlements (ManagedAttribute)
Iterator entIter = null;
try {
    QueryOptions entOptions = new QueryOptions();
    entOptions.setOrderBy("application.name");
    entOptions.setOrderAscending(true);
    entIter = context.search(ManagedAttribute.class, entOptions);
    while (entIter != null && entIter.hasNext()) {
        ManagedAttribute ma = (ManagedAttribute) entIter.next();
        Identity owner = ma.getOwner();
        String ownerIssueType = ownerIssue(owner, activeStatusAttribute, activeStatusValue);
        if (ownerIssueType != null) {
            Map f = new HashMap();
            f.put("applicationName", (ma.getApplication() != null) ? ma.getApplication().getName() : "");
            f.put("attribute", ma.getAttribute());
            f.put("value", ma.getValue());
            f.put("displayName", Util.isNotNullOrEmpty(ma.getDisplayName()) ? ma.getDisplayName() : "");
            f.put("ownerType", (owner == null) ? "N/A" : (owner.isWorkgroup() ? "Workgroup" : "Identity"));
            f.put("ownerName", (owner == null) ? "Not Found" : owner.getName());
            f.put("issueType", ownerIssueType);
            entitlementFindings.add(f);
        }
    }
} finally {
    Util.flushIterator(entIter);
}

// Prepare variables for template: pass lists directly
Map variables = new HashMap();
variables.put("adminWorkgroupName", adminWorkgroupName);
variables.put("workgroupCount", String.valueOf(workgroupFindings.size()));
variables.put("bundleCount", String.valueOf(bundleFindings.size()));
variables.put("entitlementCount", String.valueOf(entitlementFindings.size()));
variables.put("reportDate", new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date()));
variables.put("workgroupFindings", workgroupFindings);
variables.put("bundleFindings", bundleFindings);
variables.put("entitlementFindings", entitlementFindings);

// Send email if any findings
String resultMessage = "No issues found for workgroups, bundles, or entitlements owner validation.";
if (!workgroupFindings.isEmpty() || !bundleFindings.isEmpty() || !entitlementFindings.isEmpty()) {
    EmailTemplate emailTemplate = context.getObjectByName(EmailTemplate.class, emailTemplateName);
    if (emailTemplate == null) {
        throw new GeneralException("Email template '" + emailTemplateName + "' was not found.");
    }

    EmailOptions emailOptions = new EmailOptions();
    emailOptions.setTo(notificationTo);
    emailOptions.setVariables(variables);
    context.sendEmailNotification(emailTemplate, emailOptions);

    resultMessage = "Sent owner validation notification to '" + notificationTo + "' for "
            + workgroupFindings.size() + " workgroups, "
            + bundleFindings.size() + " bundles, and "
            + entitlementFindings.size() + " entitlements.";
}

if (taskResult != null) {
    taskResult.setAttribute("adminWorkgroupName", adminWorkgroupName);
    taskResult.setAttribute("emailTemplateName", emailTemplateName);
    taskResult.setAttribute("workgroupsFlagged", workgroupFindings.size());
    taskResult.setAttribute("bundlesFlagged", bundleFindings.size());
    taskResult.setAttribute("entitlementsFlagged", entitlementFindings.size());
    taskResult.setAttribute("status", resultMessage);
}

logger.debug(resultMessage);
return resultMessage;
